"""Format the approved manuscript tables from retained evidence; no evaluation."""
from __future__ import annotations

import gzip
import hashlib
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
OUT = HERE / "manuscript-tables"
SCALES = ("14M", "70M", "410M")


def write(name: str, content: str) -> None:
    (OUT / f"{name}.tex").write_text(
        "% Generated by Analysis 018 / 03_manuscript_tables.py.\n" + content + "\n",
        encoding="utf-8", newline="\n",
    )


def tabular(columns: str, header: str, rows: list[str]) -> str:
    return "\n".join([
        rf"\begin{{tabular}}{{@{{}}{columns}@{{}}}}", r"\toprule",
        header + r" \\", r"\midrule", *[r + r" \\" for r in rows],
        r"\bottomrule", r"\end{tabular}",
    ])


def fulltable(columns: str, caption: str, label: str,
              header: str, rows: list[str]) -> str:
    return "\n".join([
        r"\begin{table}[p]\centering\small\renewcommand{\arraystretch}{0.95}",
        rf"\caption{{{caption}}}\label{{{label}}}",
        tabular(columns, header, rows), r"\end{table}",
    ])


def parameter(row: dict) -> str:
    if row["dose"] is None:
        return "---"
    symbol = r"\lambda" if row["family"].startswith("A1-H-") else r"\kappa"
    return f"${symbol}={row['dose']:g}$"


def main() -> None:
    OUT.mkdir(exist_ok=True)
    evidence = HERE / "figure_data.json"
    density = HERE / "activation-density-v3-data.json"
    d = json.loads(evidence.read_text(encoding="utf-8"))
    panels = json.loads(density.read_text(encoding="utf-8"))["panels"]
    by_id = {r["id"]: r for r in d["trained"]}
    assert len(by_id) == 54 and len(d["contrasts"]) == 29
    ceilings = {r["scale"]: r["R_model_max_fraction"]
                for r in d["ceilings"] if r["family"] == "A7"}
    for r in d["trained"]:
        c = r["counts"]
        assert sum(o["zero_product_count"] for o in c["per_operation"].values()) == c["block_zero_product_count"]
        assert c["block_product_count"] + c["lm_head_product_count"] == c["model_product_count"]
        assert abs(c["block_zero_product_count"] / c["model_product_count"] - r["R_model"]) < 1e-12
    pairs = []
    for r in d["scale_pairs"]:
        a = next(t for t in d["trained"] if (t["scale"], t["family"], t["dose"]) == (r["scale"], "A4-OL1", r["dose"]))
        b = next(t for t in d["trained"] if (t["scale"], t["family"], t["dose"]) == (r["scale"], "A7-OL1", r["dose"]))
        assert abs(b["loss"] - a["loss"] - r["delta_loss"]) < 1e-12
        assert abs(100 * (b["R_model"] - a["R_model"]) - r["delta_R_pp"]) < 1e-12
        pairs.append(f"{r['scale']} & {r['dose']:g} & {r['delta_loss']:+.4f} & {r['delta_R_pp']:+.3f}")
    header = r"Size & $\kappa$ & $\Delta$ loss & $\Delta\Smodel$ (pp)"
    write("scale-contrasts-compact", tabular("lrrr", header,
          [p for p, r in zip(pairs, d["scale_pairs"]) if r["dose"] in (0, .5)]))
    write("scale-contrasts-full", fulltable("lrrr",
          "All matched A7-OL1 minus A4-OL1 comparisons. Negative loss changes and positive sparsity changes favor A7-OL1.",
          "tab:scale-pairs-full", header, pairs))
    families = ("A0", "A1-H", "A1-H-L1", "A1-H-OL1", "A4", "A4-OL1", "A7", "A7-OL1")
    ordered = sorted(d["trained"], key=lambda r: (SCALES.index(r["scale"]), families.index(r["family"]), r["dose"] or 0))
    rows = [f"{r['scale']} & {r['family']} & {parameter(r)} & {r['loss']:.4f} & {100*r['R_model']:.3f} & {100*r['R_model']/ceilings[r['scale']]:.3f}"
            for r in ordered]
    write("trained-endpoints", fulltable("lllrrr",
          r"All 54 trained endpoints. $\lambda$ is pressure weight; $\kappa$ is the trained threshold. $U_{\mathrm{arch}}=\Smodel/\Smax(\mathrm{A7})$ uses the same A7 reference within each model size, including for A0. Rounded zero sparsity need not be exactly zero.",
          "tab:trained-endpoints", r"Size & Recipe & Parameter & Loss & $\Smodel$ (\%) & $U_{\mathrm{arch}}$ (\%)", rows))
    rows = []
    blocks = list(dict.fromkeys(r["block"] for r in d["contrasts"]))
    for r in sorted(d["contrasts"], key=lambda r: (blocks.index(r["block"]), r["dose"] or 0)):
        a, b = by_id[r["reference"]], by_id[r["treatment"]]
        assert abs(b["loss"] - a["loss"] - r["delta_loss"]) < 1e-12
        assert abs(100 * (b["R_model"] - a["R_model"]) - r["delta_R_pp"]) < 1e-12
        rows.append(f"{b['family']} $-$ {a['family']} & {parameter(b)} & {r['delta_loss']:+.4f} & {r['delta_R_pp']:+.3f}")
    write("paired-effects", fulltable("llrr",
          r"All 29 Pythia-14M contrasts, treatment minus reference. When both recipes have a swept parameter, its value is matched; A0 and A1-H are fixed controls.",
          "tab:paired-effects-full", r"Treatment $-$ reference & Parameter & $\Delta$ loss & $\Delta\Smodel$ (pp)", rows))

    hist_paths = sorted((ROOT / "runs/031-2026-09-08-signed-activation-density/results/histograms").glob("*.json.gz"))
    assert len(hist_paths) == 7
    rows = []
    for path in hist_paths:
        h = json.loads(gzip.decompress(path.read_bytes()))
        family, kappa = h["source"]["family"], h["source"]["training_parameter"]
        for group, short in (("FFN activations", "FFN"), ("Attention activations", "Attention")):
            g = h["groups"][group]
            assert sum(g["histogram"]) + g["exact_zero_count"] + g["underflow"] + g["overflow"] == g["total"]
            panel = next(p for p in panels if p["group"] == group and p["kappa"] == (0 if kappa is None else kappa))
            f = panel["recipes"][family]
            zero = 100 * g["exact_zero_count"] / g["total"]
            assert abs(zero / 100 - f["zero_fraction"]) < 1e-12
            tail = 100 * (g["underflow"] + g["overflow"]) / g["total"]
            assert abs(tail / 100 - f["histogram_outside_fraction"]) < 1e-12
            zero_text = "$<0.01$" if 0 < zero < .01 else f"{zero:.2f}"
            kp = "---" if kappa is None else f"{kappa:g}"
            rows.append(f"{family} & {kp} & {short} & {zero_text} & {100*f['display_outside_fraction']:.4f} & {tail:.4f}")
    write("density-mass", tabular("lllrrr",
          r"Recipe & $\kappa$ & Group & Sparsity (\%) & View tail (\%) & Grid tail (\%)", rows))

    ops = [("qkv_projection", "QKV"), ("qk_scores", "$QK$"), ("probability_value", "$PV$"),
           ("attention_output_projection", "Attention output"), ("mlp_w1", "FFN up"), ("mlp_w2", "FFN down")]
    selected = [next(r for r in d["trained"] if (r["scale"], r["family"], r["dose"]) == (s, f, .5))
                for s in SCALES for f in ("A4-OL1", "A7-OL1")]
    rows = []
    for op, name in ops:
        rows.append(name + " & " + " & ".join(f"{100*r['counts']['per_operation'][op]['zero_product_count']/r['counts']['model_product_count']:.3f}" for r in selected))
    rows.append("Total" + " & " + " & ".join(f"{100*r['R_model']:.3f}" for r in selected))
    write("operation-contributions", tabular("lrrrrrr",
          r"& \multicolumn{2}{c}{14M} & \multicolumn{2}{c}{70M} & \multicolumn{2}{c}{410M} \\ Operation & A4-OL1 & A7-OL1 & A4-OL1 & A7-OL1 & A4-OL1 & A7-OL1", rows))
    rows = []
    labels = {"k049": "K049", "k050": "K050", "k050-attention-dense": "K050, attention dense", "k050-no-skip": "K050, all skips off", "p0": "P0 (qualified subset only)"}
    for key, r in d["runtime"]["final_candidates"].items():
        rows.append(f"{labels[key]} & {r['n']}/30 & {r['geomean']:.4f} & {r['minimum']:.4f}--{r['maximum']:.4f}")
    write("kernel-ablations", tabular("lcrr", r"Implementation & Qualified & GM speedup & Range", rows))
    source_paths = [evidence, density, *hist_paths]
    (OUT / "SOURCES.json").write_text(json.dumps({str(p.relative_to(ROOT)).replace('\\', '/'): hashlib.sha256(p.read_bytes()).hexdigest() for p in source_paths}, indent=2) + "\n", encoding="utf-8", newline="\n")
    print("Wrote 7 tables; verified 54 count totals, 44 paired contrasts and 14 pooled histograms.")


if __name__ == "__main__":
    main()
